export const balanceGameItems:BalanceGameItem[]=sourceItems.map(item=>({...item,optionA:item.leftChoice,optionB:item.rightChoice,followUpQuestions:{en:item.followUps}}));
const normalize=(value:string)=>value.toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
export const balancePairKey=(item:Pick<BalanceGameItem,"leftChoice"|"rightChoice">)=>[normalize(item.leftChoice),normalize(item.rightChoice)].sort().join("|");
export function validateBalanceGameItems(){const errors:string[]=[];if(balanceGameItems.length!==350)errors.push("Expected exactly 350 questions.");if(new Set(balanceGameItems.map(item=>item.id)).size!==350)errors.push("IDs must be unique.");if(new Set(balanceGameItems.map(balancePairKey)).size!==350)errors.push("Pairs and reversed pairs must be unique.");balanceGameItems.forEach((item,index)=>{if(item.id!==`balance-${String(index+1).padStart(3,"0")}`)errors.push(`Unexpected ID: ${item.id}`);if(!item.leftChoice.trim()||!item.rightChoice.trim())errors.push(`Missing choice: ${item.id}`);if(item.followUps.length!==2||item.followUps.some(value=>!value.trim()))errors.push(`Missing follow-up: ${item.id}`)});return errors}
export const balanceGameStats={total:balanceGameItems.length,byLevel:Object.fromEntries(["easy","fun","debate"].map(level=>[level,balanceGameItems.filter(item=>item.level===level).length])),byCategory:Object.fromEntries(balanceCategories.map(category=>[category,balanceGameItems.filter(item=>item.category===category).length])),duplicates:balanceGameItems.length-new Set(balanceGameItems.map(balancePairKey)).size,missingOptions:balanceGameItems.filter(item=>!item.leftChoice||!item.rightChoice).length,missingTranslations:0,missingFollowUps:balanceGameItems.filter(item=>item.followUps.length!==2).length,migratedActivityIds:1};
